INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.14', 1, 'Evaluate condition: 2.14 Modification of IEC
(a) Modification(s)/Updation(s) in IEC can be done online only with applicable fees
and requisite documents.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.14', 2, 'Evaluate condition: (d) RAs shall consider applications seeking modification in IEC (all numeric),
involving change in PAN, by ensuring that liabilities of the previous
applicant/applicant firm are transferred to the new applicant/applicant firm whose
PAN will be reflecting in the modified IEC.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.14', 3, 'Evaluate condition: (e) In case of change in constitution of a PAN based IEC by way of merger, acquisition,
liquidation, inheritance, business transfer etc.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.14', 4, '(f) An application for transfer of unredeemed Authorisation(s) from earlier IEC to the
new IEC may be submitted online to the original jurisdictional RA along with supporting
documents.');
