INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.20', 9, 'Run validation: 2.20 Revalidation of Import / Export Licence Certificate/ Authorisation /
Permissions for Non-SCOMET items
(a) Import Authorisation, may be revalidated, on merits for a period of six months
from date of expiry of validity by the DGFT (HQ).');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.20', 10, 'Run validation: (b) Export Authorisation, may be revalidated, on merits for a period of six months a
time and maximum upto 12 months by the DGFT (HQ).');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.20', 11, 'Run validation: (c) However, revalidation of freely transferable authorisation / duty credit scrips and
