INSERT INTO rules (rule_id, section_code, rule_text, rule_type, trigger_text, condition_text, validation_text, action_text, exception_text, output_text) VALUES ('CH2-SEC2_36-R006', '2.36', '2.36 Imports under Indo-US Memorandum of Understanding
