INSERT INTO rules (rule_id, section_code, rule_text, rule_type, trigger_text, condition_text, validation_text, action_text, exception_text, output_text) VALUES ('CH4-SEC4_12-R002', '4.12', '(iv) In such cases Authorisations shall be issued by Regional Authority concerned
