INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.12', 3, 'Evaluate condition: (iv) In such cases Authorisations shall be issued by Regional Authority concerned
under "Adhoc Norms Fixed" category and application copies need not be
forwarded to NC for fixation / ratification of norms.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.12', 4, '4.12 Entitlement
Maximum CIF value of one or more authorisations to be issued under paragraph
4.07 of Handbook of Procedures shall be as under:
(i) For Status Holders – up to 300% of FOB and / or FOR value of preceding
year’s exports and/or supplies.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.12', 5, '(iii) Once adhoc norms are fixed by Norms Committee, value limits mentioned in
sub paragraph (i) and (ii) above, would not be applicable to Advance
Authorisations issued under paragraph 4.07 of Handbook of Procedures.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.12', 6, 'Value of such authorisations, subsequent to fixation of norms by Norms
Committee, may be enhanced, if the Advance Authorisation was issued
restricting the CIF value to maximum of value in sub-paragraph (i) & (ii)
above.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.12', 7, '(iv) In such cases Authorisations shall be issued by Regional Authority concerned
under "Adhoc Norms Fixed" category and application copies need not be
forwarded to NC for fixation / ratification of norms.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.12', 8, '(vi) Norms ratified by any Norms Committee (NC) in the O/o DGFT on or after
01.04.2023 in respect of any Advance Authorisation obtained under
paragraph 4.07 shall be valid for a period of three years from the date of
ratification.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.12', 9, 'However, the Norms ratified by any Norms Committee (NC) on
or after 01.04.2015 in respect of any Advance Authorisation obtained under
paragraph 4.07 of HBP, 2015-2020 shall also be valid further upto
pg.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.12', 10, 'Run validation: 4.12 Entitlement
Maximum CIF value of one or more authorisations to be issued under paragraph
4.07 of Handbook of Procedures shall be as under:
(i) For Status Holders – up to 300% of FOB and / or FOR value of preceding
year’s exports and/or supplies.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.12', 11, 'Run validation: (iv) In such cases Authorisations shall be issued by Regional Authority concerned
under "Adhoc Norms Fixed" category and application copies need not be
forwarded to NC for fixation / ratification of norms.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.12', 12, 'Run validation: Where the application
has already been forwarded before the ratification of Norms, the Regional
Authority shall finalise the case as per the norms subsequently ratified by NC
in a similar case of the party.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('4.12', 13, 'Handle exception: However, the Norms ratified by any Norms Committee (NC) on
or after 01.04.2015 in respect of any Advance Authorisation obtained under
paragraph 4.07 of HBP, 2015-2020 shall also be valid further upto
pg.');
