INSERT INTO rules (rule_id, section_code, rule_text, rule_type, trigger_text, condition_text, validation_text, action_text, exception_text, output_text) VALUES ('CH4-SEC4_81-R016', '4.81', 'Price shall be actual price at which gold/silver/platinum is
