INSERT INTO workflows (section_code, step_index, step_text) VALUES ('6.01', 6, '(ii) STP / EHTP complexes can be set up by Central Government,
State Government, Public or Private Sector Undertakings or any
combination thereof, duly approved by Inter-Ministerial
Standing Committee (IMSC) in Ministry of Electronics &
Information Technology-Meit Y.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('6.01', 7, 'Application for setting up EHTP
/ STP unit shall be in format prescribed by Meit Y and shallbe
submitted to officer designated by Meit Y.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('6.01', 8, 'Application for setting up of BTP shall be submitted to
Department of Bio-Technology (Do BT) and such applications
which meet guidelines prescribed by Do BT will be approved and
recommended to DGFT for notification.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('6.01', 9, 'Application for setting
up of BTP unit shall be submitted to officer designated by Do BT.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('6.01', 10, 'Run validation: (b) (i) Applications for setting up units under EOU scheme shall be
approved or rejected by Units Approval Committee within 15
days, as per criteria indicated in Appendix 6A of Appendices &
ANFs and sector specific conditions relating to approval as in
Appendix 6B of Appendices & ANFs.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('6.01', 11, 'Run validation: (ii) STP / EHTP complexes can be set up by Central Government,
